import os, glob, re

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    sessions_path = os.path.join(d, '../../sessions')
    if not os.path.exists(sessions_path):
        return {}
    basename = os.path.basename(d)
    jsonl_path = os.path.join(sessions_path, basename + '.jsonl')
    try:
        t = open(jsonl_path).read().replace('\\n', '\n')
    except:
        return {}

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_str = t[m.end() : m.end() + h * w]
        try:
            # Find line breaks
            lines = re.findall(r'^([0-9 ]+(?:\n|$))', rows_str, re.MULTILINE)
            actual_rows = []
            idx = 0
            while len(actual_rows) < h and idx < len(lines):
                row_match = re.match(r'^([0-9 ]+)', lines[idx])
                if row_match:
                    actual_rows.append(list(map(int, row_match.group(1).split())))
                    idx += 1
            if len(actual_rows) == h and all(len(r) == w for r in actual_rows):
                G[k] = actual_rows
        except:
            pass
    return G

